    Collect(set, n, anims, modeGroup);
    Collect(set, n, anims, defaultGroup);
    if (anims.empty()) Collect(set, n, anims, -1);
    for (std::vector<const Anim*>::iterator it = anims.begin(); it != anims.end(); ++it) {
